package net.officefloor.hq.app.claim;

/** A claim's status. It starts DRAFT; DRAFT opens to OPEN, OPEN settles to SETTLED, and DRAFT or
 *  OPEN voids to VOID. SETTLED and VOID are final. */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** The status after moving to {@code to}; refused when this status does not allow it. */
    public ClaimStatus moveTo(ClaimStatus to) throws ClaimStatusException {
        boolean allowed = switch (to) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
        if (!allowed) {
            throw new ClaimStatusException("A " + this + " claim cannot become " + to);
        }
        return to;
    }

    /** The audit event recorded when a claim moves to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
        };
    }
}
EOF
for a in Open:OPEN Settle:SETTLED Void:VOID; do n=${a%%:*}; s=${a##*:}
cat > $J/${n}Claim.java <<EOF
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class ${n}Claim {
    public void move(@Val Claim claim) throws ClaimStatusException {
        claim.setStatus(ClaimStatus.valueOf(claim.getStatus()).moveTo(ClaimStatus.${s}).name());
    }
}
EOF
lc=$(echo $n | tr A-Z a-z)
mkdir -p "$R/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}"
cat > "$R/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}/$lc.POST.yml" <<EOF
# POST /api/sheets/{sheetId}/claims/{claimId}/$lc — move a claim to ${s}; refused (409) when its
# status does not allow it.
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: move
move:
  class: net.officefloor.hq.app.claim.${n}Claim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
EOF
done
cat > $J/RecordClaimStatus.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a status change that went through is recorded. */
public class RecordClaimStatus {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Claim claim, PersonRepository people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record(ClaimStatus.valueOf(claim.getStatus()).event() + " sheet=" + claim.getSheetId()
                + " by=" + (by == null ? "" : by)
                + " person=" + (person == null ? "" : person.getName())
                + " amount=" + claim.getAmount() + " date=" + claim.getDate());
    }
}
EOF
